# --- IR search simplified ---
def find_IR(s, ms=11, min_loop=30, max_loop=150):
    d=defaultdict(list)
    n=len(s)
    for i in range(n-ms+1): d[s[i:i+ms]].append(i)
    hits=[]
    for i in range(n-ms+1):
        for j in d.get(rc(s[i:i+ms]),()):
            loop=j-i
            if min_loop<=loop<=max_loop:
                hits.append((i+1,j+1,loop))
    # dedupe overlapping same left-arm start
    ded={}
    for a,b,lp in hits:
        if a not in ded: ded[a]=(a,b,lp)
    return list(ded.values())

